export default JSON.parse("{\"id\":\"distress_tolerance_handout_8\",\"module\":\"Distress Tolerance\",\"module_category\":\"Distress Tolerance Skills\",\"item_type\":\"handout\",\"item_number\":\"8\",\"title\":\"Self-Soothing A way to remember these skills is to think of soothing each of your five senses. With Vision: \\u0003\",\"source_marker\":\"Distress Tolerance Handout 8   (Distress Tolerance Worksheet 6\u20136b)\",\"source_pdf\":\"DBT Skills Workbook.pdf\",\"source_pdf_pages\":[358],\"source_book_pages\":[\"334\"],\"related_references\":[\"Distress Tolerance Worksheet 6\u20136b\"],\"is_example\":false,\"fillable_html_created\":false,\"keywords\":[\"Self-Soothing\",\"Vision\",\"With\",\"each\",\"five\",\"remember\",\"senses\",\"skills\",\"soothing\",\"these\",\"think\",\"your\"],\"pages\":[{\"pdf_page\":358,\"book_page\":\"334\",\"text\":\"334\\nFrom DBT Skills Training Handouts and Worksheets, Second Edition by Marsha M. Linehan. Copyright 2015 by Marsha M. Linehan. Permission\\nto photocopy this handout is granted to purchasers of this book for personal use only (see copyright page for details).\\nDistress Tolerance Handout 8   (Distress Tolerance Worksheet 6\u20136b)\\nSelf-Soothing\\nA way to remember these skills is to think of soothing each of your five senses.\\nWith Vision:\\n\\u0003\\n\u0089 Look at the stars at night.\\n\\u0003\\n\u0089 Look at pictures you like in a book.\\n\\u0003\\n\u0089 Buy one beautiful flower.\\n\\u0003\\n\u0089 Make one space in a room pleasing to look at.\\n\\u0003\\n\u0089 Light a candle and watch the flame.\\n\\u0003\\n\u0089 Set a pretty place at the table using your best\\nthings.\\n\\u0003\\n\u0089 Go people-watching or window-shopping.\\n\\u0003\\n\u0089 Go to a museum or poster shop with beautiful\\nart.\\n\\u0003\\n\u0089 Sit in the lobby of a beautiful old hotel.\\n\\u0003\\n\u0089 Look at nature around you.\\n\\u0003\\n\u0089 Walk in a pretty part of town.\\n\\u0003\\n\u0089 Watch a sunrise or a sunset.\\n\\u0003\\n\u0089 Go to a dance performance, or watch it on TV.\\n\\u0003\\n\u0089 Be mindful of each sight that passes in front of\\nyou.\\n\\u0003\\n\u0089 Take a walk in a park or a scenic hike.\\n\\u0003\\n\u0089 Browse through stores looking at things.\\n\\u0003\\n\u0089 Other:\\nWith Hearing:\\n\\u0003\\n\u0089 Listen to soothing or invigorating music.\\n\\u0003\\n\u0089 Pay attention to sounds of nature (waves,\\nbirds, rainfall, leaves rustling).\\n\\u0003\\n\u0089 Pay attention to the sounds of the city (traffic,\\nhorns, city music).\\n\\u0003\\n\u0089 Sing to your favorite songs.\\n\\u0003\\n\u0089 Hum a soothing tune.\\n\\u0003\\n\u0089 Learn to play an instrument.\\n\\u0003\\n\u0089 Burn a CD or make an iPod mix with music\\nthat will get you through tough times. Turn it\\non.\\n\\u0003\\n\u0089 Be mindful of any sounds that come your way,\\nletting them go in one ear and out the other.\\n\\u0003\\n\u0089 Turn on the radio.\\n\\u0003\\n\u0089 Other:\\nWith Smell:\\n\\u0003\\n\u0089 Use your favorite soap, shampoo, aftershave,\\ncologne, or lotions, or try them on in the store.\\n\\u0003\\n\u0089 Burn incense or light a scented candle.\\n\\u0003\\n\u0089 Open a package of coffee and inhale the\\naroma.\\n\\u0003\\n\u0089 Put lemon oil on your furniture.\\n\\u0003\\n\u0089 Put potpourri or eucalyptus oil in a bowl in your\\nroom.\\n\\u0003\\n\u0089 Sit in a new car and breathe the aroma.\\n\\u0003\\n\u0089 Boil cinnamon. Make cookies, bread, or\\npopcorn.\\n\\u0003\\n\u0089 Smell the roses.\\n\\u0003\\n\u0089 Walk in a wooded area and mindfully breathe\\nin the fresh smells of nature.\\n\\u0003\\n\u0089 Open the window and smell the air.\\n\\u0003\\n\u0089 Other:\\nWith Taste:\\n\\u0003\\n\u0089 Eat some of your favorite foods.\\n\\u0003\\n\u0089 Drink your favorite soothing drink, such\\nas herbal tea, hot chocolate, a latt\u00e9, or a\\nsmoothie.\\n\\u0003\\n\u0089 Treat yourself to a dessert.\\n\\u0003\\n\u0089 Eat macaroni and cheese or another favorite\\nchildhood food.\\n\\u0003\\n\u0089 Sample flavors in an ice cream store.\\n\\u0003\\n\u0089 Suck on a piece of peppermint candy.\\n\\u0003\\n\u0089 Chew your favorite gum.\\n\\u0003\\n\u0089 Get a little bit of a special food you don\u2019t\\nusually spend the money on, such as fresh-\\nsqueezed orange juice or your favorite candy.\\n\\u0003\\n\u0089 Really taste the food you eat. Eat one thing\\nmindfully.\\n\\u0003\\n\u0089 Other:\\nWith Touch:\\n\\u0003\\n\u0089 Take a long hot bath or shower.\\n\\u0003\\n\u0089 Pet your dog or cat.\\n\\u0003\\n\u0089 Have a massage. Soak your feet.\\n\\u0003\\n\u0089 Put creamy lotion on your whole body.\\n\\u0003\\n\u0089 Put a cold compress on your forehead.\\n\\u0003\\n\u0089 Sink into a comfortable chair in your home.\\n\\u0003\\n\u0089 Put on a blouse or shirt that has a pleasant\\nfeel.\\n\\u0003\\n\u0089 Take a drive with the car windows rolled down.\\n\\u0003\\n\u0089 Run your hand along smooth wood or leather.\\n\\u0003\\n\u0089 Hug someone.\\n\\u0003\\n\u0089 Put clean sheets on the bed.\\n\\u0003\\n\u0089 Wrap up in a blanket.\\n\\u0003\\n\u0089 Notice touch that is soothing.\\n\\u0003\\n\u0089 Other:\"}],\"full_text\":\"Distress Tolerance Handout 8   (Distress Tolerance Worksheet 6\u20136b)\\nSelf-Soothing\\nA way to remember these skills is to think of soothing each of your five senses.\\nWith Vision:\\n\\u0003\\n\u0089 Look at the stars at night.\\n\\u0003\\n\u0089 Look at pictures you like in a book.\\n\\u0003\\n\u0089 Buy one beautiful flower.\\n\\u0003\\n\u0089 Make one space in a room pleasing to look at.\\n\\u0003\\n\u0089 Light a candle and watch the flame.\\n\\u0003\\n\u0089 Set a pretty place at the table using your best\\nthings.\\n\\u0003\\n\u0089 Go people-watching or window-shopping.\\n\\u0003\\n\u0089 Go to a museum or poster shop with beautiful\\nart.\\n\\u0003\\n\u0089 Sit in the lobby of a beautiful old hotel.\\n\\u0003\\n\u0089 Look at nature around you.\\n\\u0003\\n\u0089 Walk in a pretty part of town.\\n\\u0003\\n\u0089 Watch a sunrise or a sunset.\\n\\u0003\\n\u0089 Go to a dance performance, or watch it on TV.\\n\\u0003\\n\u0089 Be mindful of each sight that passes in front of\\nyou.\\n\\u0003\\n\u0089 Take a walk in a park or a scenic hike.\\n\\u0003\\n\u0089 Browse through stores looking at things.\\n\\u0003\\n\u0089 Other:\\nWith Hearing:\\n\\u0003\\n\u0089 Listen to soothing or invigorating music.\\n\\u0003\\n\u0089 Pay attention to sounds of nature (waves,\\nbirds, rainfall, leaves rustling).\\n\\u0003\\n\u0089 Pay attention to the sounds of the city (traffic,\\nhorns, city music).\\n\\u0003\\n\u0089 Sing to your favorite songs.\\n\\u0003\\n\u0089 Hum a soothing tune.\\n\\u0003\\n\u0089 Learn to play an instrument.\\n\\u0003\\n\u0089 Burn a CD or make an iPod mix with music\\nthat will get you through tough times. Turn it\\non.\\n\\u0003\\n\u0089 Be mindful of any sounds that come your way,\\nletting them go in one ear and out the other.\\n\\u0003\\n\u0089 Turn on the radio.\\n\\u0003\\n\u0089 Other:\\nWith Smell:\\n\\u0003\\n\u0089 Use your favorite soap, shampoo, aftershave,\\ncologne, or lotions, or try them on in the store.\\n\\u0003\\n\u0089 Burn incense or light a scented candle.\\n\\u0003\\n\u0089 Open a package of coffee and inhale the\\naroma.\\n\\u0003\\n\u0089 Put lemon oil on your furniture.\\n\\u0003\\n\u0089 Put potpourri or eucalyptus oil in a bowl in your\\nroom.\\n\\u0003\\n\u0089 Sit in a new car and breathe the aroma.\\n\\u0003\\n\u0089 Boil cinnamon. Make cookies, bread, or\\npopcorn.\\n\\u0003\\n\u0089 Smell the roses.\\n\\u0003\\n\u0089 Walk in a wooded area and mindfully breathe\\nin the fresh smells of nature.\\n\\u0003\\n\u0089 Open the window and smell the air.\\n\\u0003\\n\u0089 Other:\\nWith Taste:\\n\\u0003\\n\u0089 Eat some of your favorite foods.\\n\\u0003\\n\u0089 Drink your favorite soothing drink, such\\nas herbal tea, hot chocolate, a latt\u00e9, or a\\nsmoothie.\\n\\u0003\\n\u0089 Treat yourself to a dessert.\\n\\u0003\\n\u0089 Eat macaroni and cheese or another favorite\\nchildhood food.\\n\\u0003\\n\u0089 Sample flavors in an ice cream store.\\n\\u0003\\n\u0089 Suck on a piece of peppermint candy.\\n\\u0003\\n\u0089 Chew your favorite gum.\\n\\u0003\\n\u0089 Get a little bit of a special food you don\u2019t\\nusually spend the money on, such as fresh-\\nsqueezed orange juice or your favorite candy.\\n\\u0003\\n\u0089 Really taste the food you eat. Eat one thing\\nmindfully.\\n\\u0003\\n\u0089 Other:\\nWith Touch:\\n\\u0003\\n\u0089 Take a long hot bath or shower.\\n\\u0003\\n\u0089 Pet your dog or cat.\\n\\u0003\\n\u0089 Have a massage. Soak your feet.\\n\\u0003\\n\u0089 Put creamy lotion on your whole body.\\n\\u0003\\n\u0089 Put a cold compress on your forehead.\\n\\u0003\\n\u0089 Sink into a comfortable chair in your home.\\n\\u0003\\n\u0089 Put on a blouse or shirt that has a pleasant\\nfeel.\\n\\u0003\\n\u0089 Take a drive with the car windows rolled down.\\n\\u0003\\n\u0089 Run your hand along smooth wood or leather.\\n\\u0003\\n\u0089 Hug someone.\\n\\u0003\\n\u0089 Put clean sheets on the bed.\\n\\u0003\\n\u0089 Wrap up in a blanket.\\n\\u0003\\n\u0089 Notice touch that is soothing.\\n\\u0003\\n\u0089 Other:\",\"copyright_notice\":\"Extracted from user-provided PDF: DBT Skills Training Handouts and Worksheets, Second Edition by Marsha M. Linehan. Respect source copyright and purchaser-use limits.\",\"created_at\":\"2026-06-25T17:33:54\",\"json_path\":\"json/items/distress_tolerance/handouts/distress_tolerance_handout_8_self_soothing_a_way_to_remember_these_skills_is_to_think_of_soothing_e.json\",\"ourspace_shared_life_filter\":{\"revision_id\":\"ourspace_shared_life_filter_v1\",\"title\":\"Self-Soothing A way to remember these skills is to think of soothing each of your five senses. With Vision: \\u0003\",\"domain\":\"distress_tolerance\",\"item_type\":\"handout\",\"shared_facing_summary\":\"Distress tolerance means getting through the wave without adding harm. Use gentle, medically safer versions first.\",\"tiny_steps\":[\"Lower danger first.\",\"Reduce stimulation.\",\"Send a one-line safety/capacity message.\",\"Choose one body-safe skill for 30 seconds.\",\"Reassess before doing more.\"],\"flare_day_versions\":{\"minimum\":\"One breath, one label, one safe message, or one checkbox.\",\"medium\":\"Two to five minutes with everything reachable from bed/chair.\",\"full\":\"Use the original worksheet/handout when both bodies and brains have capacity.\"},\"accessibility_modifications\":[\"Replace intense exercise with hand squeeze, paced exhale, safe fidget, weighted comfort if tolerated, or visual grounding.\",\"Avoid cold shock/breath-holding/intense exercise unless already clinician-approved and safe that day.\",\"Keep oxygen, rescue meds, allergy plan, mobility aids, and exit routes accessible.\"],\"relationship_and_caregiver_notes\":[\"William's needs and Jasper's capacity both count.\",\"Ask before helping; ask before escalating; name the smallest next step.\",\"Pause means pause, not abandonment. I am coming back. I care about us. I need a smaller next step.\",\"What is needed, what capacity exists, what can be smaller, and what can wait?\"],\"identity_and_trauma_filter\":[\"Use William's masculine language and Jasper's they/them language.\",\"Use consent-based, non-shaming, body-neutral language unless a person has explicitly chosen a term.\",\"Do not turn symptoms, dysphoria, trauma responses, clutter, fatigue, or emotional intensity into moral failure.\"],\"avoid_or_adjust\":[\"Do not use crisis skills as punishment, sensory flooding, or exposure without consent.\"],\"suggested_cadence\":[\"daily_optional\",\"flare_day_as_needed\"],\"app_tags\":[\"adhd_friendly\",\"disability_first\",\"distress_tolerance\",\"shared\",\"tiny_steps\",\"trauma_informed\"]},\"ourspace_shared_revision_metadata\":{\"source_path\":\"DBT+ADHD Skill Files/05_DBT_Distress_Tolerance/handouts/json/distress_tolerance_handout_8_self_soothing_a_way_to_remember_these_skills_is_to_think_of_soothing_e.json\",\"shared_output_path\":\"shared/05_dbt_distress_tolerance/handouts_json/distress_tolerance_handout_8_self_soothing_a_way_to_remember_these_skills_688b40a9.json\",\"revised_at_utc\":\"2026-06-26T00:24:16Z\",\"copyright_note\":\"Extracted from user-provided PDF: DBT Skills Training Handouts and Worksheets, Second Edition by Marsha M. Linehan. Respect source copyright and purchaser-use limits.\"},\"shared_json_path\":\"shared/05_dbt_distress_tolerance/handouts_json/distress_tolerance_handout_8_self_soothing_a_way_to_remember_these_skills_688b40a9.json\"}");
